const source = $json.markdown ?? '';

const cleaned = source
  // Удаляем только изображения, но сохраняем текстовые ссылки
  .replace(/!\[[^\]]*]\([^)]+\)/g, '')

  // Убираем дополнительный Outlook SafeLink из title.
  // Основная ссылка остаётся без изменений:
  // [текст](основной-url "дублирующий-url") → [текст](основной-url)
  .replace(
    /\[([^\]]*)\]\((https?:\/\/[^\s)]+)\s+"[^"]*"\)/g,
    '[$1]($2)'
  )

  // Удаляем пустые ссылки без текста
  .replace(/\[\s*]\([^)]+\)/g, '')

  // Удаляем технические строки из десятков дефисов
  .replace(/^[\s|]*-{20,}[\s|]*$/gm, '')

  // Удаляем пустые Markdown-заголовки
  .replace(/^\s*#{1,6}\s*$/gm, '')

  // Убираем пробелы в конце строк
  .replace(/[ \t]+$/gm, '')

  // Ограничиваем количество пустых строк
  .replace(/\n{4,}/g, '\n\n\n')

  .trim();

const trigger = $('Email Trigger (IMAP)').first().json;

return {
  json: {
    subject: trigger.subject ?? 'Без темы',
    from: trigger.from ?? '',
    cleanedMarkdown: cleaned,
    charactersBefore: source.length,
    charactersAfter: cleaned.length,
  },
};

const content = $json.html ?? '';

const fullHtml = `<!doctype html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
