      padding: 24px;
      box-shadow: 0 6px 24px rgba(0, 0, 0, 0.08);
      overflow-wrap: anywhere;
    }

    h1, h2, h3, h4, h5, h6 {
      line-height: 1.25;
      margin-top: 1.6em;
      margin-bottom: 0.65em;
      color: #111827;
    }

    h1 {
      font-size: 30px;
    }

    h2 {
      font-size: 24px;
      padding-bottom: 8px;
      border-bottom: 1px solid #e5e7eb;
    }

    h3 {
      font-size: 21px;
    }

    h4 {
      font-size: 19px;
    }

    p {
      margin: 0 0 1em;
      font-size: 17px;
    }

    ul, ol {
      padding-left: 24px;
      margin: 0 0 1.2em;
    }

    li {
      margin-bottom: 0.55em;
      font-size: 17px;
    }

    blockquote {
      margin: 1.4em 0;
      padding: 12px 16px;
      border-left: 4px solid #9ca3af;
      background: #f9fafb;
    }

    a {
      color: #2563eb;
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    strong {
      color: #111827;
    }

    hr {
      border: 0;
      border-top: 1px solid #e5e7eb;
      margin: 2em 0;
    }

    @media (max-width: 600px) {
      .page {
        padding: 0;
      }

      .article {
        border-radius: 0;
        padding: 20px 16px 40px;
        box-shadow: none;
      }

      h1 {
        font-size: 26px;
      }

      h2 {
        font-size: 22px;
      }

      h3 {
        font-size: 20px;
      }

      p, li {
        font-size: 17px;
      }
    }
  </style>
</head>

<body>
  <main class="page">
    <article class="article">
      ${content}
    </article>
  </main>
</body>
</html>`;

return {
  json: {
    htmlDocument: fullHtml,
  },
};
